import { OFFICIAL_LOGOS } from './brand.js';
import {cleanImportedState} from './data/import-cleanup.js';
import { storage,readUserState,writeUserState,getLegacyOwner,legacyAlreadyClaimed,markLegacyClaimed,legacyHasPersonalData } from './data/repository.js';
import { previewLocalMigration } from './data/migration-preflight.js';
import { dateISO, offsetDate, seed } from './domain/initial-state.js';
import { getInitialView } from './domain/startup-route.js';
import {account,onAccountChange,initAccount,login,signup,logout,linkAccount,fetchCloudData,scheduleAccountSync,hasAccountConflict,changeAccountMode,accountInitial,resumePendingSync} from './account.js';
import {renderAccount,renderAuthGate,renderLegacyChoice} from './account-ui.js';


(()=>{'use strict';



let state;try{state=storage.read()||seed();if(!Array.isArray(state.records)||!Array.isArray(state.routines)||!Array.isArray(state.habits))throw Error('Formato inválido')}catch(e){state=seed()}
const freshState=()=>({...seed(),version:3,demo:false,routines:[],records:[],habits:[],checks:{},draft:null});
const app={activeUid:null,needLegacyChoice:false,view:getInitialView(state),tab:'gym',activity:'walk',filter:'all',record:null,routine:null,editor:null,habit:null,exerciseSearch:'',modal:null,toast:''};
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z"/><path d="M9 21v-8h6v8"/>',activity:'<path d="M6.5 6.5 17.5 17.5M4 9l5-5M2 7l5-5M15 20l5-5M17 22l5-5"/>',progress:'<path d="M3 19V5m0 14h18M7 16l5-5 4 3 5-7"/>',habits:'<rect x="3" y="4" width="18" height="17" rx="2"/><path d="M8 2v4m8-4v4M3 10h18m-13 5 2 2 4-4"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-1.8 1.8-.06-.06a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1.05 1.57V21h-2.5v-.08a1.7 1.7 0 0 0-1.05-1.57 1.7 1.7 0 0 0-1.88.34l-.06.06-1.8-1.8.06-.06A1.7 1.7 0 0 0 8.1 16a1.7 1.7 0 0 0-1.57-1.05H6.4v-2.5h.09A1.7 1.7 0 0 0 8.1 11.4a1.7 1.7 0 0 0-.34-1.88L7.7 9.46l1.8-1.8.06.06a1.7 1.7 0 0 0 1.88.34 1.7 1.7 0 0 0 1.05-1.57V6.4H15v.09a1.7 1.7 0 0 0 1.05 1.57 1.7 1.7 0 0 0 1.88-.34l.06-.06 1.8 1.8-.06.06A1.7 1.7 0 0 0 19.4 11.4a1.7 1.7 0 0 0 1.57 1.05H21v2.5h-.09A1.7 1.7 0 0 0 19.4 15"/>',arrow:'<path d="m9 18 6-6-6-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};
const icon=(n)=>`<svg aria-hidden="true" viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${icons[n]||icons.arrow}</svg>`;
const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{if(!account.authenticated||!app.activeUid||app.needLegacyChoice)return;storage.write(state);applyTheme();scheduleAccountSync(JSON.parse(JSON.stringify(state)))};
const applyTheme=()=>{let t=state.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):state.theme;document.documentElement.dataset.theme=t;document.querySelector('meta[name=theme-color]').content=t==='dark'?'#111716':'#f2f4f1'};
matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',applyTheme);
const navs=[['home','Inicio'],['activity','Actividad'],['progress','Progreso'],['habits','Hábitos']];
const mainView=v=>({home:'home',activity:'activity',routine:'activity',routineEdit:'activity',exerciseLibrary:'activity',session:'activity',otherForm:'activity',progress:'progress',record:'progress',habits:'habits',habitEdit:'habits',settings:'settings',account:'account',onboard:'home'}[v]||'home');
const go=v=>{if(!account.authenticated||app.needLegacyChoice)return;if(hasAccountConflict())v='account';app.view=v;window.scrollTo({top:0,behavior:'instant'});render()};
const toast=s=>{app.toast=s;let el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=s;document.querySelectorAll('.toast').forEach(x=>x.remove());document.body.appendChild(el);setTimeout(()=>el.remove(),2400)};
const title=(head,sub,action='')=>`<div class="row between wrap" style="align-items:end;margin:7px 0 21px"><div><h1 style="font-size:clamp(29px,4vw,43px);margin:0 0 8px">${head}</h1><p class="sub" style="margin:0">${sub}</p></div>${action}</div>`;
const back=(dest='activity')=>`<button class="back" data-action="go" data-value="${dest}">← Volver</button>`;
const button=(label,action,value='',cls='')=>`<button class="btn ${cls}" data-action="${action}" data-value="${h(value)}">${label}</button>`;
const getWeek=()=>Array.from({length:7},(_,i)=>offsetDate(i-6));
const sessionsWeek=()=>state.records.filter(r=>getWeek().includes(r.date));
const countMin=r=>r.reduce((sum,x)=>sum+Number(x.minutes||0),0);
const weekDay=iso=>new Date(`${iso}T12:00:00`).toLocaleDateString('es-AR',{weekday:'short'}).replace('.','');
const graph=()=>{const days=getWeek(),vals=days.map(d=>countMin(state.records.filter(r=>r.date===d))),max=Math.max(60,...vals);return `<div class="chart" role="img" aria-label="Minutos registrados en los últimos siete días: ${vals.join(', ')}"><div style="display:none">${vals.join(', ')}</div>${days.map((d,i)=>`<div class="barcol"><div class="bar ${vals[i]?'':'empty'}" style="height:${Math.max(5,Math.round(vals[i]/max*100))}%" title="${vals[i]} minutos"></div><span class="barlabel">${weekDay(d).slice(0,3)}</span></div>`).join('')}</div>`};
const bars=()=>`<div class="card"><div class="chart-card-header"><div><h3 style="margin:0">Actividad semanal</h3><div class="micro">Minutos por día · últimos 7 días</div></div><div class="chart-mini-photo" role="img" aria-label="Fotografía editorial de entrenamiento"></div></div>${graph()}<div class="row between" style="margin-top:14px"><small class="muted">${countMin(sessionsWeek())} minutos registrados</small><button class="btn small outline" data-action="go" data-value="progress">Ver progreso ${icon('arrow')}</button></div></div>`;
const brandMarkup=()=>`<span class="brand-slot" role="img" aria-label="Percí"><img class="brand-img-dark" alt="" src="${OFFICIAL_LOGOS.horizDark}"><img class="brand-img-light" alt="" src="${OFFICIAL_LOGOS.horizLight}"></span>`;
const iconMarkup=(cls='')=>`<span class="official-symbol ${cls}" role="img" aria-label="Isotipo original de Percí"><img class="brand-img-dark" alt="" src="${OFFICIAL_LOGOS.iconDark}"><img class="brand-img-light" alt="" src="${OFFICIAL_LOGOS.iconLight}"></span>`;
const navbtn=([key,label])=>`<button class="navbtn ${mainView(app.view)===key?'active':''}" data-action="go" data-value="${key}" aria-label="${label}" ${mainView(app.view)===key?'aria-current="page"':''}>${icon(key)}<span>${label}</span></button>`;
const shell=body=>`<div class="app"><aside class="rail" aria-label="Navegación principal"><div class="logo">${brandMarkup()}</div><nav class="nav">${navs.map(navbtn).join('')}</nav><div class="rail-bottom"><button class="navbtn ${app.view==='account'?'active':''}" data-action="go" data-value="account">${icon('home')}<span>Mi cuenta</span></button><button class="navbtn ${app.view==='settings'?'active':''}" data-action="go" data-value="settings">${icon('settings')}<span>Ajustes</span></button><div class="status"><span class="dot"></span>Tus datos están guardados</div></div></aside><main class="main"><header class="top"><div class="mobile-logo">${brandMarkup()}</div><div class="eyebrow">PERCÍ / TU ESPACIO DE PROGRESO</div><div class="topright"><button class="iconbtn" data-action="go" data-value="settings" title="Ajustes" aria-label="Ajustes">${icon('settings')}</button><button class="avatar ${app.view==='account'?'active':''}" data-action="go" data-value="account" title="Mi cuenta" aria-label="Abrir Mi cuenta">${h(accountInitial(account.user)||'•')}</button></div></header>${body}<footer class="footer-note">Percí · Tu progreso, a tu ritmo. · Mobile first · Dark / Light · PWA</footer></main><nav class="mobile-nav" aria-label="Navegación inferior">${navs.map(navbtn).join('')}</nav></div>${app.modal?renderModal():''}`;
function renderHome(){const sw=sessionsWeek();const next=state.routines[0];const action=state.draft?button('▶ Continuar sesión','continue','',''):state.focus==='others'?button('Registrar actividad ↗','other','walk'):next?button('Empezar a entrenar ↗','start',next.id):button('Crear primera rutina ↗','editRoutine','new');const secondary=state.focus==='others'?button('Ver rutinas','go','activity','outline'):button('Registrar otra actividad','other','walk','outline');return `<div class="home-head"><div class="eyebrow">TU ESPACIO. TU RITMO.</div><h1>Construí tu progreso.</h1><p class="sub">Cada sesión suma. Lo importante es que sea tuyo.</p></div><section class="hero" aria-label="Entrenamiento destacado"><div class="hero-content"><div class="eyebrow">${state.draft?'SESIÓN EN CURSO':'TU PRÓXIMO MOVIMIENTO'}</div><h1>${state.draft?'Tu sesión te espera.':state.focus==='others'?'Movete a tu manera.':next?'Una buena sesión empieza acá.':'Empezá por lo que te mueve.'}</h1><p>${state.draft?'Retomá exactamente donde dejaste tu entrenamiento.':state.focus==='others'?'Caminata, running, bici o deporte. Registrá lo que disfrutás.':next?`${h(next.name)} · ${next.exercises.length} ejercicios. Listo cuando vos estés listo.`:'Armá una rutina propia o registrá tu actividad favorita.'}</p><div class="row wrap">${action}</div></div><div class="hero-flair">ENFOQUE · CONSTANCIA · PROGRESO</div></section><div class="section-head"><h2>Una mirada a tu semana</h2><span class="micro">${state.demo?'Datos ilustrativos':'Datos locales'}</span></div><div class="grid3"><div class="card"><div class="kpi-icon">◷</div><div class="kpi-val">${sw.length}</div><div class="kpi-label">Actividades</div></div><div class="card"><div class="kpi-icon">↗</div><div class="kpi-val">${countMin(sw)}</div><div class="kpi-label">Minutos activos</div></div><div class="card"><div class="kpi-icon">✓</div><div class="kpi-val">${state.habits.filter(x=>!x.paused&&getDueToday(x)).length?Math.round(state.habits.filter(x=>!x.paused&&getDueToday(x)&&state.checks[`${x.id}:${dateISO()}`]).length/state.habits.filter(x=>!x.paused&&getDueToday(x)).length*100)+'%':'—'}</div><div class="kpi-label">Hábitos de hoy</div></div></div><div class="section-head"><h2>Tu actividad, en perspectiva</h2></div><div class="grid2">${bars()}<div class="card"><div class="row between"><div><h3>Pequeños compromisos</h3><div class="micro">Hábitos programados hoy</div></div><button class="btn small outline" data-action="go" data-value="habits">Ver todos</button></div>${renderHabitMini()}<div class="divider"></div><p class="micro">Una pausa programada no interrumpe tu progreso.</p></div></div><div class="section-head"><h2>¿Qué te gustaría hacer hoy?</h2></div><div class="twocol"><div class="photo-card" style="--photo:url('https://images.unsplash.com/photo-1517836357463-d25dfeac3438?w=700&q=80'),linear-gradient(130deg,#264a45,#17201e)"><div class="eyebrow">FUERZA Y GIMNASIO</div><h3>Entrená con foco.</h3><button class="btn small" data-action="go" data-value="activity">Ver rutinas ↗</button></div><div class="photo-card" style="--photo:url('https://images.unsplash.com/photo-1552674605-db6ffd4facb5?w=700&q=80'),linear-gradient(130deg,#264a45,#17201e)"><div class="eyebrow">MOVIMIENTO LIBRE</div><h3>Registrá tu actividad.</h3><button class="btn small" data-action="other" data-value="walk">Registrar ↗</button></div></div>`}
function getDueToday(x){return x.days.includes(new Date().getDay())}
function renderHabitMini(){let list=state.habits.filter(x=>!x.paused&&getDueToday(x));return list.length?list.map(x=>`<div class="listrow"><div class="bubble">✦</div><div class="grow"><strong>${h(x.name)}</strong><div class="micro">Hoy</div></div><button class="habit-done ${state.checks[`${x.id}:${dateISO()}`]?'on':''}" data-action="toggleHabit" data-value="${x.id}" aria-label="Completar ${h(x.name)}">${state.checks[`${x.id}:${dateISO()}`]?'✓':'○'}</button></div>`).join(''):`<div class="empty"><div class="emoji">☼</div>No hay hábitos programados hoy.</div>`}
const categories=[['walk','Caminata','🚶'],['run','Running','🏃'],['cycle','Bicicleta','🚴'],['sport','Deporte','🏐'],['other','Otra','✦']];
function renderActivity(){return `${title('Tu movimiento, a tu manera.','Entrená con una rutina o registrá otra actividad. Todo cuenta.') }<div class="tabbar" role="tablist" aria-label="Tipo de actividad"><button class="tab ${app.tab==='gym'?'active':''}" data-action="tab" data-value="gym">Gimnasio</button><button class="tab ${app.tab==='other'?'active':''}" data-action="tab" data-value="other">Otras actividades</button></div>${app.tab==='gym'?`<div class="row between wrap" style="margin:8px 0 17px"><h2>Mis rutinas</h2>${button('+ Crear rutina','editRoutine','new','small')}</div>${state.routines.length?`<div class="grid2">${state.routines.map((r,i)=>`<div class="card" style="padding:0;overflow:hidden"><div class="image-strip" style="${i%2?'background-image:linear-gradient(90deg,#17201ed9,#17201e20),url(https://images.unsplash.com/photo-1517836357463-d25dfeac3438?w=900&q=80),linear-gradient(130deg,#264a45,#17201e)':''}">RUTINA ${String(i+1).padStart(2,'0')}</div><div style="padding:20px"><h3>${h(r.name)}</h3><p class="micro">${r.exercises.length} ejercicios · ${r.exercises.reduce((a,e)=>a+Number(e.sets),0)} series</p><div class="row wrap">${button('Ver rutina ↗','detailRoutine',r.id,'small')}${button('Empezar','start',r.id,'small ghost')}</div></div></div>`).join('')}</div>`:`<div class="card empty"><div class="emoji">🏋️</div><h3>Tu primera rutina empieza acá.</h3><p>No te mostramos una sesión para iniciar hasta que tengas una rutina real.</p>${button('Crear mi rutina','editRoutine','new')}</div>`}<div class="section-head"><h2>Biblioteca de ejercicios</h2></div><div class="card"><div class="row between wrap"><div><h3 style="margin:0 0 5px">Encontrá tu próximo ejercicio</h3><p class="micro" style="margin:0">Seleccioná, organizá y personalizá tu entrenamiento.</p></div>${button('Explorar ejercicios','library','','small outline')}</div></div>`:`<div class="photo-card" style="min-height:196px;--photo:url('https://images.unsplash.com/photo-1552674605-db6ffd4facb5?w=900&q=80'),linear-gradient(130deg,#264a45,#17201e)"><div class="eyebrow">MOVIMIENTO SIN ETIQUETAS</div><h3>Elegí la actividad, después registrá lo importante.</h3></div><div class="section-head"><h2>¿Qué hiciste hoy?</h2></div><div class="grid3" style="grid-template-columns:repeat(auto-fit,minmax(140px,1fr))">${categories.map(([key,label,emoji])=>`<button class="card" data-action="other" data-value="${key}" style="text-align:left;min-height:120px"><span style="font-size:27px">${emoji}</span><h3 style="font-size:17px;margin:13px 0 0">${label}</h3><span class="micro">Registrar ↗</span></button>`).join('')}</div>`}`}
const lib=['Press de banca','Sentadilla','Peso muerto','Remo con mancuerna','Press militar','Jalón al pecho','Prensa de piernas','Curl de bíceps','Plancha','Elevación lateral','Hip thrust','Dominadas'];
function renderLibrary(){return `<div class="detail-top">${back(app.editor?'routineEdit':'activity')}<span class="micro">BIBLIOTECA</span></div>${title('Biblioteca de ejercicios','Encontrá movimientos por nombre o añadí uno propio.') }<div class="field"><label for="libsearch">Buscar ejercicio</label><div class="row"><input id="libsearch" placeholder="Ej. Sentadilla" value="${h(app.exerciseSearch)}"/><button class="btn" data-action="searchLibrary">Buscar</button></div></div><div class="card">${lib.filter(e=>e.toLowerCase().includes(app.exerciseSearch.toLowerCase())).map(e=>`<div class="listrow"><div class="bubble">✦</div><div class="grow"><strong>${h(e)}</strong><div class="micro">Fuerza · biblioteca base</div></div>${app.editor?button('+ Añadir','addExercise',e,'small'):button('Ver rutinas','go','activity','small outline')}</div>`).join('')||'<div class="empty">No encontramos coincidencias. Podés crear un ejercicio personalizado.</div>'}<div class="divider"></div>${app.editor?`<div class="field"><label for="customexercise">Ejercicio personalizado</label><div class="row"><input id="customexercise" maxlength="80" placeholder="Nombre del ejercicio"/><button class="btn small" data-action="addCustomExercise">Añadir</button></div></div>`:''}</div>`}
function renderRoutine(){const r=state.routines.find(x=>x.id===app.routine);if(!r)return renderActivity();return `<div class="detail-top">${back()}<span class="micro">DETALLE DE RUTINA</span></div><div class="photo-card" style="min-height:240px;--photo:url('https://images.unsplash.com/photo-1517836357463-d25dfeac3438?w=1100&q=80'),linear-gradient(130deg,#264a45,#17201e)"><div class="eyebrow">TU PRÓXIMA SESIÓN</div><h2 style="color:#fff">${h(r.name)}</h2><div class="row wrap">${button('▶ Empezar entrenamiento','start',r.id,'small')}</div></div><div class="section-head"><h2>Plan de entrenamiento</h2>${button('Editar rutina','editRoutine',r.id,'small outline')}</div><div class="card">${r.exercises.map((e,i)=>`<div class="listrow"><div class="bubble">${String(i+1).padStart(2,'0')}</div><div class="grow"><strong>${h(e.name)}</strong><div class="micro">${e.sets} series · ${e.reps} repeticiones objetivo</div></div></div>`).join('')}</div><div class="row wrap" style="margin-top:16px">${button('Empezar ahora','start',r.id,'wide')}${button('Duplicar','duplicateRoutine',r.id,'outline')}${button('Eliminar','deleteRoutine',r.id,'outline')}</div>`}
function renderRoutineEdit(){const e=app.editor||{id:null,name:'',exercises:[]};return `<div class="detail-top">${back(e.id?'routine':'activity')}<span class="micro">${e.id?'EDITAR':'NUEVA'} RUTINA</span></div>${title(e.id?'Editá tu rutina':'Creá una rutina propia','Planificá el entrenamiento. Registrarlo será otra acción, cuando lo realices.') }<div class="card"><div class="field"><label for="rname">Nombre de la rutina *</label><input id="rname" maxlength="80" value="${h(e.name)}" placeholder="Ej. Tren superior A"/></div><div class="section-head"><h2>Ejercicios (${e.exercises.length})</h2>${button('+ Añadir ejercicio','library','','small outline')}</div>${e.exercises.length?e.exercises.map((item,i)=>`<div class="exercise-row" data-exrow="${i}"><div class="row between"><strong>${h(item.name)}</strong><button class="btn small outline" data-action="removeExercise" data-value="${i}">Quitar</button></div><div class="inline2" style="margin-top:12px"><div><label>Series</label><input data-field="sets" type="number" min="1" max="15" value="${item.sets}"/></div><div><label>Reps objetivo</label><input data-field="reps" type="number" min="1" max="100" value="${item.reps}"/></div></div></div>`).join(''):`<div class="empty">Todavía no agregaste ejercicios.<br/>Usá la biblioteca para empezar.</div>`}<div class="row wrap" style="margin-top:17px">${button('Guardar rutina','saveRoutine')} ${button('Cancelar','cancelEdit','','outline')}</div></div>`}
function renderSession(){const d=state.draft;if(!d)return '<div class="empty">No hay sesión activa.</div>';const r=state.routines.find(x=>x.id===d.routineId)||{name:'Sesión',exercises:d.snapshot};const items=d.snapshot||r.exercises;const total=items.reduce((sum,e)=>sum+Number(e.sets),0);const completed=Object.values(d.sets||{}).filter(Boolean).length;return `<div class="detail-top">${back('activity')}<span class="badge good">● Guardado localmente</span></div><div class="sessionhead"><div class="eyebrow">ENTRENAMIENTO EN CURSO</div><h2 style="margin:10px 0">${h(r.name)}</h2><p class="micro">Registrá cada serie. Podés salir y continuar más tarde.</p><div class="row between"><strong>${completed} / ${total} series</strong><span class="micro">${Math.round(completed/Math.max(1,total)*100)}% completado</span></div><div class="progressline" style="margin-top:10px"><span style="width:${completed/Math.max(1,total)*100}%"></span></div></div><div class="section-head"><h2>Tu sesión</h2><span class="badge">Sincronización nube: no disponible</span></div>${items.map((item,i)=>`<div class="card" style="margin-bottom:14px"><div class="row between"><div><div class="eyebrow">EJERCICIO ${i+1}/${items.length}</div><h3>${h(item.name)}</h3><div class="micro">Objetivo ${item.reps} reps · ${item.sets} series</div></div><span class="help-icon">${i+1}</span></div>${Array.from({length:Number(item.sets)},(_,j)=>{const k=`${i}-${j}`,o=d.sets[k]||{};return `<div class="setrow" data-set="${k}"><div class="num">${j+1}</div><div><label>Peso (kg)</label><input type="number" min="0" step="0.5" placeholder="0" data-field="weight" value="${o.weight??''}" aria-label="Peso serie ${j+1} de ${h(item.name)}"/></div><div><label>Reps</label><input type="number" min="0" max="100" data-field="reps" placeholder="${item.reps}" value="${o.reps??item.reps}" aria-label="Repeticiones serie ${j+1} de ${h(item.name)}"/></div><button class="${o.done?'done':''}" data-action="toggleSet" data-value="${k}" aria-label="${o.done?'Desmarcar':'Completar'} serie ${j+1}">${o.done?'✓':'○'}</button></div>`}).join('')}</div>`).join('')}<div class="card"><div class="row between wrap"><div><h3 style="margin-bottom:4px">${completed===total?'Sesión completa':'Avanzá a tu ritmo'}</h3><p class="micro" style="margin:0">Cada serie confirmada queda en el borrador de este navegador.</p></div>${button('Finalizar sesión','finishSession')}</div></div>`}
function renderOtherForm(){const [key,label,emoji]=categories.find(x=>x[0]===app.activity)||categories[0];const wantsDist=['walk','run','cycle'].includes(key);return `<div class="detail-top">${back('activity')}<span class="micro">REGISTRO DE ACTIVIDAD</span></div>${title(`${emoji} ${label}`,'Solo los datos que importan para esta actividad.') }<div class="card" style="max-width:680px"><div class="field"><label for="adate">Fecha</label><input type="date" id="adate" value="${dateISO()}"/></div>${key==='sport'?'<div class="field"><label for="aname">¿Qué deporte practicaste? *</label><input id="aname" placeholder="Ej. Vóley, fútbol" maxlength="60"/></div>':key==='other'?'<div class="field"><label for="aname">Nombre de la actividad *</label><input id="aname" placeholder="Ej. Yoga, baile" maxlength="60"/></div>':''}<div class="field"><label for="amins">Duración (minutos) *</label><input id="amins" type="number" min="1" max="1440" placeholder="Ej. 40"/></div>${wantsDist?'<div class="field"><label for="adistance">Distancia (km) · opcional</label><input id="adistance" type="number" min="0" max="1000" step="0.01" placeholder="Ej. 4.2"/></div>':''}<div class="field"><label for="anote">Nota · opcional</label><textarea id="anote" maxlength="400" placeholder="¿Cómo te sentiste?"></textarea></div><div class="notice">✓ Sin GPS ni sensores. La actividad se guarda primero en este dispositivo y se respalda cuando la cuenta está vinculada y hay conexión.</div><div class="row wrap" style="margin-top:17px">${button('Guardar actividad','saveActivity')} ${button('Cancelar','go','activity','outline')}</div></div>`}
function renderProgress(){const categories2=[['all','Todas'],['gym','Fuerza'],['walk','Caminata'],['run','Running'],['cycle','Bici'],['sport','Deporte'],['other','Otras']];const list=state.records.filter(r=>app.filter==='all'||r.type===app.filter).sort((a,b)=>b.date.localeCompare(a.date));const mins=countMin(list);return `${title('El progreso también se ve.','Un historial compartido, métricas específicas y contexto para cada actividad.')}<div class="feature-photo" role="img" aria-label="Fotografía deportiva de personas corriendo"><div><div class="eyebrow">TU HISTORIA EN MOVIMIENTO</div><h2>Cada entrenamiento cuenta.</h2><p>Progreso real, a tu ritmo.</p></div></div><div class="grid2">${bars()}<div class="card"><h3>Tu recorrido</h3><p class="micro">Últimos 7 días · datos ${state.demo?'ilustrativos':'registrados localmente'}</p><div class="tiles"><div class="tile"><div class="val">${sessionsWeek().length}</div><div class="micro">Sesiones</div></div><div class="tile"><div class="val">${countMin(sessionsWeek())}</div><div class="micro">Minutos</div></div><div class="tile"><div class="val">${sessionsWeek().filter(x=>x.type==='gym').length}</div><div class="micro">Fuerza</div></div></div><div class="section-head"><h3 style="font-size:17px">Días con actividad</h3></div><div class="week">${getWeek().map(d=>`<div class="day ${d===dateISO()?'today':''}"><span>${weekDay(d).slice(0,3)}</span><b>${d.slice(-2)}</b>${state.records.some(r=>r.date===d)?'<i></i>':'<span style="height:6px"></span>'}</div>`).join('')}</div></div></div><div class="section-head"><h2>Historial</h2><span class="micro">${list.length} registros</span></div><div class="filterline">${categories2.map(([k,l])=>`<button class="chip ${app.filter===k?'active':''}" data-action="filter" data-value="${k}">${l}</button>`).join('')}</div><div class="card">${list.length?list.map(r=>`<div class="listrow"><div class="bubble">${categories.find(x=>x[0]===r.type)?.[2]||'🏋️'}</div><div class="grow"><strong>${h(r.name)}</strong><div class="micro">${new Date(r.date+'T12:00:00').toLocaleDateString('es-AR',{day:'numeric',month:'short'})} · ${r.minutes} min ${r.distance?'· '+r.distance+' km':''} ${r.setsDone?'· '+r.setsDone+' series':''}</div></div><button class="mini" data-action="detailRecord" data-value="${r.id}" aria-label="Ver registro ${h(r.name)}">Ver ${icon('arrow')}</button></div>`).join(''):`<div class="empty"><div class="emoji">◌</div><h3>Sin registros por ahora</h3><p>Cuando registres una actividad, aparecerá acá sin inventar estadísticas.</p>${button('Registrar actividad','go','activity')}</div>`}</div>`}
function renderRecord(){const r=state.records.find(x=>x.id===app.record);if(!r)return renderProgress();return `<div class="detail-top">${back('progress')}<span class="micro">DETALLE / EDITAR REGISTRO</span></div>${title(h(r.name),'Cada registro tiene sus datos, sin mezclar disciplinas.') }<div class="card" style="max-width:670px"><div class="tiles"><div class="tile"><div class="val">${r.minutes}</div><div class="micro">Minutos</div></div><div class="tile"><div class="val">${r.distance??r.setsDone??'—'}</div><div class="micro">${r.distance?'Km':r.setsDone?'Series':'Dato adicional'}</div></div><div class="tile"><div class="val">${r.volume??'—'}</div><div class="micro">${r.volume?'Volumen kg':'Volumen'}</div></div></div><div class="divider"></div><div class="field"><label for="rdate">Fecha</label><input type="date" id="rdate" value="${h(r.date)}"/></div><div class="field"><label for="rmin">Duración (minutos)</label><input type="number" id="rmin" min="1" max="1440" value="${r.minutes}"/></div>${r.distance!==undefined?`<div class="field"><label for="rdist">Distancia (km)</label><input type="number" id="rdist" min="0" step="0.01" value="${r.distance??''}"/></div>`:''}<div class="field"><label for="rnote">Nota</label><textarea id="rnote">${h(r.note??'')}</textarea></div>${r.type==='gym'?'<p class="fieldhint">Las series completadas se muestran como referencia; esta iteración permite editar la duración, fecha y notas del registro.</p>':''}<div class="row wrap" style="margin-top:17px">${button('Guardar cambios','saveRecord')}${button('Eliminar registro','deleteRecord','','outline')}</div></div>`}
function renderHabits(){const due=state.habits.filter(h=>!h.paused&&getDueToday(h));const checked=due.filter(x=>state.checks[`${x.id}:${dateISO()}`]).length;return `${title('Los pequeños pasos importan.','Los hábitos acompañan tu entrenamiento, no lo reemplazan.',button('+ Crear hábito','editHabit','new','small'))}<div class="grid2"><div class="card"><div class="row between"><div><h3>Hoy</h3><p class="micro" style="margin:0">${checked} de ${due.length} hábitos programados</p></div><span class="kpi-val" style="font-size:31px">${due.length?Math.round(checked/due.length*100)+'%':'—'}</span></div><div class="progressline" style="margin-top:15px"><span style="width:${due.length?checked/due.length*100:0}%"></span></div><div class="divider"></div>${renderHabitMini()}</div><div class="card"><h3>Calendario de esta semana</h3><p class="micro">Los días libres no cuentan como incumplimiento.</p><div class="week">${getWeek().map(d=>{const dt=new Date(d+'T12:00:00');let programmed=state.habits.filter(x=>!x.paused&&x.days.includes(dt.getDay()));return `<div class="day ${d===dateISO()?'today':''}"><span>${weekDay(d).slice(0,3)}</span><b>${d.slice(-2)}</b><i style="background:${programmed.length&&programmed.every(x=>state.checks[`${x.id}:${d}`])?'var(--accent)':'var(--muted2)'};opacity:${programmed.length?1:.15}"></i></div>`}).join('')}</div></div></div><div class="section-head"><h2>Mis hábitos</h2><span class="micro">${state.habits.length} configurados</span></div><div class="card">${state.habits.length?state.habits.map(x=>`<div class="listrow"><div class="bubble">${x.paused?'⏸':'✦'}</div><div class="grow"><strong>${h(x.name)}</strong> ${x.paused?'<span class="badge">Pausado</span>':''}<div class="micro">${x.days.length===7?'Todos los días':x.days.map(i=>['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'][i]).join(', ')}</div></div><button class="mini" data-action="editHabit" data-value="${x.id}">Editar</button></div>`).join(''):`<div class="empty">Todavía no creaste hábitos.<br/>${button('Crear uno','editHabit','new')}</div>`}</div>`}
function renderHabitEdit(){const x=app.habit||{id:null,name:'',days:[1,2,3,4,5],paused:false};return `<div class="detail-top">${back('habits')}<span class="micro">${x.id?'EDITAR':'NUEVO'} HÁBITO</span></div>${title(x.id?'Editar hábito':'Un hábito a la vez.','Elegí el nombre y los días que tienen sentido para vos.') }<div class="card" style="max-width:650px"><div class="field"><label for="hname">Nombre *</label><input id="hname" maxlength="70" value="${h(x.name)}" placeholder="Ej. Estirar 10 minutos"/></div><div class="field"><label>Días programados *</label><div class="checkbox-group">${['D','L','M','M','J','V','S'].map((s,i)=>`<label class="checkday" title="${['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'][i]}"><input type="checkbox" name="hdays" value="${i}" ${x.days.includes(i)?'checked':''}/>${s}</label>`).join('')}</div><div class="fieldhint">Un día no programado se considera descanso, no falta.</div></div><div class="row wrap">${button('Guardar hábito','saveHabit')}${x.id?button(x.paused?'Reanudar':'Pausar','pauseHabit',x.id,'outline'):''}${x.id?button('Eliminar','deleteHabit',x.id,'outline'):''}</div></div>`}
function renderSettings(){return `${title('Tu espacio, a tu modo.','Personalizá Percí a tu ritmo.')}<div class="grid2"><div class="card"><h3>Apariencia</h3><p class="micro">Elegí cómo querés ver Percí.</p><div class="filterline">${[['dark','Oscuro'],['light','Claro'],['system','Automático']].map(([k,v])=>`<button class="chip ${state.theme===k?'active':''}" data-action="theme" data-value="${k}">${v}</button>`).join('')}</div><div class="divider"></div><h3>Tu actividad principal</h3><p class="micro">Podés cambiarla cuando quieras; siempre tendrás acceso a todas tus actividades.</p><div class="filterline">${[['gym','Gimnasio'],['others','Otras actividades'],['both','Ambas']].map(([k,v])=>`<button class="chip ${state.focus===k?'active':''}" data-action="focus" data-value="${k}">${v}</button>`).join('')}</div><div class="divider"></div>${button('Volver a ver bienvenida','onboard','','outline')}</div><div class="card"><h3>Privacidad y tus datos</h3><div class="notice"><strong>✓ Tus datos se guardan en este dispositivo.</strong><p class="micro" style="margin:8px 0 0">${account.linked?'También tenés una copia vinculada a tu cuenta.':'Podés respaldar tus avances desde Mi cuenta.'}</p></div><div class="row wrap" style="margin-top:18px">${button('Mi cuenta','go','account')}${button('Exportar copia de mis datos','export','','outline')}</div><p class="micro" style="margin-top:16px">Si necesitás recuperar un archivo de respaldo, podés importarlo sin borrar nada hasta que lo confirmes.</p>${button('Importar copia JSON','import','','outline')}${storage.hasBackup()?button('Revertir última importación','restoreBackup','','outline'):''}</div></div>`}
function renderOnboard(){return `<div style="max-width:675px;margin:35px auto 0"><div class="onboard-visual">${iconMarkup('onboard-brand')}</div><div class="eyebrow">BIENVENIDO A PERCÍ</div><h1>Tu progreso. Sin comparaciones.</h1><p class="sub">Entrená, movete, registrá tus avances y construí hábitos a tu propio ritmo. Empezá por lo que te interesa.</p><div class="card"><h3>¿Qué te gustaría priorizar?</h3><p class="micro">Podés cambiarlo después y siempre verás todas las actividades.</p><div class="filterline">${[['gym','Gimnasio'],['others','Otras actividades'],['both','Ambas']].map(([k,v])=>`<button class="chip ${state.focus===k?'active':''}" data-action="focus" data-value="${k}">${v}</button>`).join('')}</div><h3 style="margin-top:23px">¿Cómo preferís visualizar Percí?</h3><div class="filterline">${[['dark','Oscuro'],['light','Claro'],['system','Automático']].map(([k,v])=>`<button class="chip ${state.theme===k?'active':''}" data-action="theme" data-value="${k}">${v}</button>`).join('')}</div><div class="row wrap" style="margin-top:17px">${button('Entrar a Percí ↗','finishOnboard')}${button('Omitir por ahora','finishOnboard','','outline')}</div></div></div>`}
function renderModal(){const m=app.modal;if(!m)return '';return `<div class="modal-wrap" role="presentation"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><h2 id="modalTitle">${h(m.title)}</h2><p class="sub">${h(m.body)}</p>${m.extra||''}<div class="row wrap">${button(h(m.confirmLabel||'Confirmar'),m.confirm,m.value||'',m.danger?'danger':'')}${button('Cancelar','closeModal','','outline')}</div></div></div>`}
function render(){
  applyTheme();
  const root=document.getElementById('root');
  if(!account.ready||!account.authenticated){root.innerHTML=renderAuthGate();return;}
  if(app.needLegacyChoice){root.innerHTML=renderLegacyChoice();return;}
  if(!app.activeUid){root.innerHTML=renderAuthGate();return;}
  let view=app.view;
  let out=({home:renderHome,activity:renderActivity,progress:renderProgress,habits:renderHabits,settings:renderSettings,account:renderAccount,routine:renderRoutine,routineEdit:renderRoutineEdit,exerciseLibrary:renderLibrary,session:renderSession,otherForm:renderOtherForm,record:renderRecord,habitEdit:renderHabitEdit,onboard:renderOnboard}[view]||renderHome)();
  root.innerHTML=shell(out);
}
function activateAccountData(){
  const id=account.user?.id;
  if(!account.authenticated||!id){
    app.activeUid=null;app.needLegacyChoice=false;storage.activateUser(null);state=freshState();app.view='home';return;
  }
  if(app.activeUid===id)return;
  const scoped=readUserState(id);
  app.activeUid=id;
  storage.activateUser(id);
  app.modal=null;
  if(scoped){state=scoped;app.needLegacyChoice=false;app.view=getInitialView(state);return;}
  const legacy=storage.readLegacy();
  const owner=getLegacyOwner();
  if(!legacyAlreadyClaimed() && legacyHasPersonalData(legacy) && (!owner||owner===id)){
    app.needLegacyChoice=true;state=freshState();app.view='home';return;
  }
  state=freshState();storage.write(state);app.needLegacyChoice=false;app.view=getInitialView(state);
}
function decideLegacy(copyLegacy){
  if(!app.needLegacyChoice||!account.authenticated||!app.activeUid)return;
  if(copyLegacy){
    const legacy=storage.readLegacy();
    if(!legacy)throw new Error('No encontramos los datos anteriores.');
    // El dato original permanece inalterado; solo copiamos al espacio de esta cuenta.
    state=JSON.parse(JSON.stringify(legacy));
  }else{state=freshState();}
  storage.write(state);
  markLegacyClaimed();
  app.needLegacyChoice=false;
  app.view=getInitialView(state);
  render();
}

const get=id=>document.getElementById(id);
const showModal=(title,body,confirm,value='',danger=false,extra='',confirmLabel='Confirmar')=>{app.modal={title,body,confirm,value,danger,extra,confirmLabel};render()};
const validDate=v=>/^\d{4}-\d{2}-\d{2}$/.test(v)&&!isNaN(new Date(v+'T12:00:00').getTime());
const id=()=>Math.random().toString(36).slice(2,10);
function persistEditor(){if(!app.editor)return;const name=get('rname');if(name)app.editor.name=name.value;document.querySelectorAll('[data-exrow]').forEach(x=>{const i=Number(x.dataset.exrow);app.editor.exercises[i].sets=Number(x.querySelector('[data-field=sets]').value)||1;app.editor.exercises[i].reps=Number(x.querySelector('[data-field=reps]').value)||1})}
function handle(action,value){switch(action){
case 'go':app.modal=null;go(value);break;
case 'tab':app.tab=value;render();break;
case 'filter':app.filter=value;render();break;
case 'theme':state.theme=value;save();render();break;
case 'focus':state.focus=value;save();render();break;
case 'finishOnboard':state.onboardSeen=true;save();go('home');break;
case 'onboard':go('onboard');break;
case 'detailRoutine':app.routine=value;go('routine');break;
case 'editRoutine':{let r=state.routines.find(x=>x.id===value);app.editor=r?JSON.parse(JSON.stringify(r)):{id:null,name:'',exercises:[]};app.routine=r?.id||null;go('routineEdit');break}
case 'cancelEdit':app.editor=null;go('activity');break;
case 'library':if(app.view==='routineEdit')persistEditor();app.exerciseSearch='';go('exerciseLibrary');break;
case 'searchLibrary':app.exerciseSearch=get('libsearch').value.trim();render();break;
case 'addExercise':app.editor.exercises.push({name:value,sets:3,reps:10});go('routineEdit');toast('Ejercicio añadido');break;
case 'addCustomExercise':{let n=get('customexercise')?.value.trim();if(!n){toast('Ingresá un nombre');break}app.editor.exercises.push({name:n.slice(0,80),sets:3,reps:10});go('routineEdit');break}
case 'removeExercise':persistEditor();app.editor.exercises.splice(Number(value),1);render();break;
case 'saveRoutine':{persistEditor();const e=app.editor;if(!e.name?.trim()){toast('Poné un nombre a la rutina');break}if(!e.exercises.length){toast('Añadí al menos un ejercicio');break}if(e.exercises.some(x=>x.sets<1||x.sets>15||x.reps<1||x.reps>100)){toast('Revisá series y repeticiones');break}const r={id:e.id||id(),name:e.name.trim(),exercises:e.exercises};let k=state.routines.findIndex(x=>x.id===r.id);if(k>=0)state.routines[k]=r;else state.routines.push(r);app.routine=r.id;app.editor=null;save();go('routine');toast('Rutina guardada en este dispositivo');break}
case 'duplicateRoutine':{let r=state.routines.find(x=>x.id===value);if(!r)break;let c=JSON.parse(JSON.stringify(r));c.id=id();c.name+=' · copia';state.routines.push(c);save();app.routine=c.id;render();toast('Copia creada');break}
case 'deleteRoutine':showModal('¿Eliminar rutina?','No se eliminarán registros de sesiones que ya realizaste.','confirmDeleteRoutine',value,true);break;
case 'confirmDeleteRoutine':state.routines=state.routines.filter(x=>x.id!==value);app.modal=null;save();go('activity');toast('Rutina eliminada');break;
case 'start':{if(state.draft){showModal('Tenés una sesión en curso','Primero retomá o finalizá tu sesión actual. No se crearán dos sesiones por error.','continue');break}const r=state.routines.find(x=>x.id===value);if(!r)break;state.draft={id:id(),routineId:r.id,snapshot:JSON.parse(JSON.stringify(r.exercises)),startedAt:Date.now(),sets:{}};save();go('session');break}
case 'continue':app.modal=null;go('session');break;
case 'toggleSet':{const d=state.draft;if(!d)break;const row=document.querySelector(`[data-set="${value}"]`);let weight=Number(row.querySelector('[data-field=weight]').value),reps=Number(row.querySelector('[data-field=reps]').value);const prev=d.sets[value];if(prev?.done)d.sets[value]={weight:prev.weight,reps:prev.reps,done:false};else{if(!Number.isFinite(weight)||weight<0||reps<1||reps>100){toast('Revisá peso y repeticiones');break}d.sets[value]={weight,reps,done:true}}save();render();break}
case 'finishSession':{let d=state.draft;if(!d)break;let done=Object.values(d.sets).filter(x=>x.done);if(!done.length){toast('Confirmá al menos una serie');break}showModal('¿Finalizar sesión?',`Se guardarán ${done.length} series confirmadas en el historial local. Podés seguir editando antes de finalizar.`,'confirmFinish','',false,'','Finalizar');break}
case 'confirmFinish':{let d=state.draft;if(!d)break;let r=state.routines.find(x=>x.id===d.routineId);let sets=Object.values(d.sets).filter(x=>x.done);let vol=sets.reduce((s,x)=>s+(Number(x.weight)||0)*(Number(x.reps)||0),0);state.records.unshift({id:id(),type:'gym',name:r?.name||'Entrenamiento de fuerza',date:dateISO(),minutes:Math.max(1,Math.round((Date.now()-d.startedAt)/60000)),setsDone:sets.length,volume:Math.round(vol),note:''});state.draft=null;app.modal=null;save();go('progress');toast('Sesión guardada localmente ✓');break}
case 'other':app.activity=value||'walk';go('otherForm');break;
case 'saveActivity':{let type=app.activity,name=categories.find(x=>x[0]===type)?.[1];const duration=Number(get('amins')?.value),date=get('adate')?.value;const custom=get('aname')?.value.trim();if(['sport','other'].includes(type)){if(!custom){toast('Completá el nombre de la actividad');break}name=custom}if(!duration||duration<1||duration>1440||!validDate(date)){toast('Completá fecha y duración válidas');break}let distance=get('adistance')?.value;if(distance!==undefined&&distance!==''&&(!Number.isFinite(Number(distance))||Number(distance)<0)){toast('Revisá la distancia');break}state.records.unshift({id:id(),type,name:name.slice(0,80),minutes:duration,date,note:get('anote').value.trim(),...(distance?{distance:Number(distance)}:{})});save();go('progress');toast('Actividad guardada localmente ✓');break}
case 'detailRecord':app.record=value;go('record');break;
case 'saveRecord':{let r=state.records.find(x=>x.id===app.record);if(!r)break;let dur=Number(get('rmin').value),dt=get('rdate').value;if(!dur||dur<1||dur>1440||!validDate(dt)){toast('Revisá fecha y duración');break}r.minutes=dur;r.date=dt;r.note=get('rnote').value.trim();if(get('rdist'))r.distance=Math.max(0,Number(get('rdist').value)||0);save();go('progress');toast('Registro actualizado');break}
case 'deleteRecord':showModal('¿Eliminar este registro?','Esta acción es irreversible dentro del historial actual.','confirmDeleteRecord',app.record,true);break;
case 'confirmDeleteRecord':state.records=state.records.filter(x=>x.id!==value);app.modal=null;save();go('progress');toast('Registro eliminado');break;
case 'editHabit':app.habit=value==='new'?{id:null,name:'',days:[1,2,3,4,5],paused:false}:JSON.parse(JSON.stringify(state.habits.find(x=>x.id===value)));go('habitEdit');break;
case 'saveHabit':{let n=get('hname').value.trim(),days=[...document.querySelectorAll('[name=hdays]:checked')].map(x=>Number(x.value));if(!n||!days.length){toast('Poné nombre y elegí al menos un día');break}let habit={id:app.habit.id||id(),name:n.slice(0,70),days,paused:app.habit.paused||false};let i=state.habits.findIndex(x=>x.id===habit.id);if(i>=0)state.habits[i]=habit;else state.habits.push(habit);save();go('habits');toast('Hábito guardado');break}
case 'pauseHabit':{let x=state.habits.find(x=>x.id===value);x.paused=!x.paused;save();go('habits');toast(x.paused?'Hábito pausado':'Hábito reanudado');break}
case 'deleteHabit':showModal('¿Eliminar hábito?','Se eliminará la configuración de este hábito.','confirmDeleteHabit',value,true);break;
case 'confirmDeleteHabit':state.habits=state.habits.filter(x=>x.id!==value);app.modal=null;save();go('habits');break;
case 'toggleHabit':{let x=state.habits.find(x=>x.id===value);if(!x||x.paused||!getDueToday(x))break;const k=`${value}:${dateISO()}`;state.checks[k]=!state.checks[k];save();render();break}
case 'closeModal':app.modal=null;render();break;
case 'checkMigration':{const review=previewLocalMigration(state);const c=review.counts;const summary=review.ready?`Estructura válida: ${c.routines} rutinas, ${c.exercises} ejercicios, ${c.records} actividades, ${c.habits} hábitos y ${c.completions} cumplimientos.`:`Encontramos ${review.errors.length} problemas: ${review.errors.slice(0,3).join(' ')}`;showModal('Verificación local para migración',summary+' '+review.warnings.join(' '),'closeModal','',false,'','Cerrar');break}
case 'export':{let a=document.createElement('a'),blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});a.href=URL.createObjectURL(blob);a.download='perci_prototipo_datos.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Exportación local iniciada');break}
case 'import':showModal('Importar archivo JSON','Se revisará el formato antes de confirmar el reemplazo de datos locales.','checkImport','',false,'<div class="field"><label for="importfile">Archivo .json</label><input type="file" accept="application/json,.json" id="importfile"/></div>','Revisar archivo');break;
case 'checkImport':{let file=get('importfile').files[0];if(!file){toast('Elegí un archivo');break}file.text().then(t=>{try{const data=JSON.parse(t);if(!Array.isArray(data.routines)||!Array.isArray(data.records)||!Array.isArray(data.habits)||!data.checks)throw Error();app.pendingImport=cleanImportedState(data);const cleaned=app.pendingImport;showModal('Datos listos para importar',`Se reemplazarán ${state.records.length} registros por ${cleaned.records.length} registros y ${cleaned.routines.length} rutinas del archivo. Los registros demostrativos serán excluidos si el respaldo los identifica como demo. Guardaremos una copia de respaldo local.`,'confirmImport','',true,'','Reemplazar datos')}catch(e){app.modal=null;render();toast('Formato de archivo no válido')}});break}
case 'confirmImport':{storage.backup(state);state={...seed(),...app.pendingImport,theme:state.theme,onboardSeen:true,demo:false};app.pendingImport=null;app.modal=null;save();go('home');toast('Importación completada localmente');break}
case 'restoreBackup':showModal('¿Revertir última importación?','Se reemplazarán los datos actuales por la copia anterior a la última importación.','confirmRestoreBackup','',true);break;
case 'confirmRestoreBackup':{try{const prev=storage.readBackup();if(!prev||!Array.isArray(prev.records))throw Error();state=prev;storage.clearBackup();app.modal=null;save();go('home');toast('Copia anterior restaurada')}catch(e){app.modal=null;render();toast('No encontramos una copia válida')}break}
case 'clearDemo':showModal('¿Vaciar datos de ejemplo?','Se dejarán rutinas, registros y hábitos en blanco para que pruebes los estados vacíos.','confirmClear','',true,'','Vaciar demo');break;
case 'confirmClear':state={...state,demo:false,routines:[],records:[],habits:[],checks:{},draft:null};app.modal=null;save();go('home');toast('Modo vacío listo');break;
case 'resetDemo':showModal('¿Restaurar datos de demostración?','Se reemplazarán tus datos locales de prueba por ejemplos.','confirmReset','',true,'','Restaurar');break;
case 'confirmReset':{const t=state.theme,f=state.focus;state={...seed(),theme:t,focus:f,onboardSeen:true};app.modal=null;save();go('home');toast('Demo restaurada');break}
}}
document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();handle(el.dataset.action,el.dataset.value||'')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&app.modal){app.modal=null;render()}});
// Safari puede recuperar una pestaña anterior desde Back/Forward Cache.
// Si aquella pestaña estaba en Ajustes, al reabrir la app volvemos al
// punto de entrada correcto sin borrar ni alterar la rutina guardada.
window.addEventListener('pageshow', event => {
  if (event.persisted && app.view === 'settings') {
    app.modal = null;
    app.view = getInitialView(state);
    render();
  }
});
// Cuenta personal. Tokens de Supabase nunca se guardan en localStorage.
document.addEventListener('submit',async event=>{
  if(event.target.id!=='account-auth-form')return;
  event.preventDefault();
  const email=get('account-email')?.value||'';
  const password=get('account-password')?.value||'';
  if(event.target.dataset.mode==='register'){
    await signup(get('account-name')?.value||'',email,password,get('account-confirm')?.value||'');
  }else{
    await login(email,password);
  }
});
document.addEventListener('click',async event=>{
  const action=event.target.closest('[data-account-action]')?.dataset.accountAction;
  if(!action)return;
  event.preventDefault();
  if(action==='show-register'){changeAccountMode('register');return;}
  if(action==='show-login'){changeAccountMode('login');return;}
  if(action==='claim-legacy'||action==='skip-legacy'){
    try{decideLegacy(action==='claim-legacy');}catch(error){window.alert(error.message||'No pudimos recuperar tus rutinas.');}
    return;
  }
  if(action==='logout'){await logout();return;}
  if(action==='link'||action==='sync'){
    if(action==='link'&&!window.confirm('¿Querés guardar una copia de tus rutinas en tu cuenta? Los datos de ejemplo se excluyen.'))return;
    await linkAccount(JSON.parse(JSON.stringify(state)));
  }
  if(action==='recover'){
    if(!window.confirm('¿Recuperar los datos de tu cuenta? Vamos a hacer un respaldo local y unir los registros sin reemplazar los existentes.'))return;
    try{
      const remote=await fetchCloudData();
      if(!remote || !Array.isArray(remote.routines))throw Error('Respuesta inválida');
      storage.backup(state);
      const merge=(local,cloud)=>{const ids=new Set(local.map(x=>x.id));return local.concat(cloud.filter(x=>!ids.has(x.id)));};
      state.routines=merge(state.routines.filter(x=>x.id!=='r1'),remote.routines);
      const realRecords=state.records.filter(x=>!state.demo||!['s1','s2','s3'].includes(x.id));
      const realHabits=state.habits.filter(x=>!state.demo||!['h1','h2'].includes(x.id));
      state.records=merge(realRecords,remote.records);
      state.habits=merge(realHabits,remote.habits);
      state.checks={...(state.demo?{}:state.checks),...remote.checks};
      state.demo=false;state.onboardSeen=true;
      save();go('home');toast('Tus datos se recuperaron y tu copia local anterior quedó respaldada');
    }catch(err){toast(err.message||'No pudimos recuperar tu cuenta');}
  }
});
let wasOffline=false;
let lastOnlineUserId=null;
onAccountChange(()=>{
  const recovered=wasOffline&&!account.offline;
  const onlineUserId=account.authenticated&&!account.offline?account.user?.id:null;
  const onlineSessionStarted=!!onlineUserId && onlineUserId!==lastOnlineUserId;
  wasOffline=account.offline;
  lastOnlineUserId=onlineUserId;
  activateAccountData();
  if(hasAccountConflict())app.view='account';
  render();
  if((recovered||onlineSessionStarted)&&account.authenticated&&account.linked&&!app.needLegacyChoice){
    resumePendingSync(JSON.parse(JSON.stringify(state)));
  }
});
applyTheme();render();
initAccount().catch(()=>{});
})();
